    },
    {
      "id": "REQ-INVALID-NOOP",
      "theorem": "RingBuffer.req_invalid_noop",
      "statement": "InvalidNoop step",
      "text": "REQ-INVALID-NOOP: every invalid operation is rejected and leaves the state unchanged."
    },
    {
      "id": "REQ-WELL-FORMED",
      "theorem": "RingBuffer.req_well_formed",
      "statement": "KeepsWellFormed step",
      "text": "REQ-WELL-FORMED: every operation on a well-formed state yields a well-formed state."
    },
    {
      "id": "REQ-ENQUEUE-EFFECTS",
      "theorem": "RingBuffer.req_enqueue_effects",
      "statement": "EnqueueEffects step",
      "text": "REQ-ENQUEUE-EFFECTS: a successful enqueue returns `ok`, writes the value into slot `slot s s.count` and no other slot, increments `count`, and keeps `capacity` and `head`."
    },
    {
      "id": "REQ-DEQUEUE-EFFECTS",
      "theorem": "RingBuffer.req_dequeue_effects",
      "statement": "DequeueEffects step",
      "text": "REQ-DEQUEUE-EFFECTS: a successful dequeue returns the value in slot `head`, advances `head` by one slot modulo `capacity`, decrements `count`, and keeps every slot."
    },
    {
      "id": "REQ-ENQUEUE-CONTENTS",
      "theorem": "RingBuffer.req_enqueue_contents",
      "statement": "EnqueueContents step",
      "text": "REQ-ENQUEUE-CONTENTS: a successful enqueue appends the value to the stored values."
    },
    {
      "id": "REQ-DEQUEUE-CONTENTS",
      "theorem": "RingBuffer.req_dequeue_contents",
      "statement": "DequeueContents step",
      "text": "REQ-DEQUEUE-CONTENTS: a successful dequeue returns the oldest stored value and removes exactly that value."
    },
    {
      "id": "REQ-FIFO",
      "theorem": "RingBuffer.req_fifo",
      "statement": "Fifo step",
      "text": "REQ-FIFO: over any sequence of operations, the starting values followed by the accepted values equal the delivered values followed by the final stored values."
    }
  ],
